rol" type="date" name="due_at" value="{{ old('due_at',$invoice?->due_at?->format('Y-m-d')) }}"></div><div class="col-md-3"><label class="form-label">Invoice discount</label><input class="form-control" name="discount_total" value="{{ old('discount_total',$invoice?->discount_total??0) }}"></div><div class="col-md-3"><label class="form-label">Fees</label><input class="form-control" name="fee_total" value="{{ old('fee_total',$invoice?->fee_total??0) }}"></div></div><hr><h5>Items</h5><div id="invoiceItems">@php($itemRows=old('items',$invoice?->items?->toArray()??[['description'=>'','quantity'=>1,'unit_price'=>0,'discount'=>0,'tax_rate'=>0]]))@foreach($itemRows as $i=>$item)<div class="row g-2 mb-2 invoice-item"><div class="col-md-4"><input class="form-control" name="items[{{ $i }}][description]" value="{{ $item['description'] }}" placeholder="Description" required></div><div class="col"><input class="form-control" name="items[{{ $i }}][quantity]" value="{{ $item['quantity'] }}" placeholder="Qty" required></div><div class="col"><input class="form-control" name="items[{{ $i }}][unit_price]" value="{{ $item['unit_price'] }}" placeholder="Unit price" required></div><div class="col"><input class="form-control" name="items[{{ $i }}][discount]" value="{{ $item['discount']??0 }}" placeholder="Discount"></div><div class="col"><input class="form-control" name="items[{{ $i }}][tax_rate]" value="{{ $item['tax_rate']??0 }}" placeholder="Tax %"></div><div class="col-auto"><button type="button" class="btn btn-outline-danger remove-item">×</button></div></div>@endforeach</div><button type="button" id="addInvoiceItem" class="btn btn-outline-primary btn-sm">Add item</button><hr><div class="row g-3"><div class="col-md-6"><label class="form-label">Notes</label><textarea class="form-control" name="notes" rows="4">{{ old('notes',$invoice?->notes) }}</textarea></div><div class="col-md-6"><label class="form-label">Terms</label><textarea class="form-control" name="terms" rows="4">{{ old('terms',$invoice?->terms) }}</textarea></div></div><button class="btn btn-primary mt-3">Save invoice</button></form></div></div>@endsection
@push('scripts')<script>document.addEventListener('DOMContentLoaded',()=>{const box=document.querySelector('#invoiceItems');document.querySelector('#addInvoiceItem').onclick=()=>{const i=box.children.length;const row=box.firstElementChild.cloneNode(true);row.querySelectorAll('input').forEach((x)=>{x.name=x.name.replace(/items\[\d+]/,`items[${i}]`);x.value=x.name.includes('quantity')?'1':'0';if(x.name.includes('description'))x.value='';});box.append(row)};box.addEventListener('click',e=>{if(e.target.classList.contains('remove-item')&&box.children.length>1)e.target.closest('.invoice-item').remove()})});</script>@endpush
